args.command:
python3 - <<'EOF'
import workcell, itertools
cx, cy = 397.26, 280.81
for dx in [0,-0.5,0.5,-1.0,1.0,-1.5,1.5]:
    for dy in [0,-0.5,0.5,-1.0,1.0,-1.5,1.5]:
        r = workcell.call("robot","insert",str(cx+dx),str(cy+dy))
        print(dx,dy,r.text)
        if r.ok and "did not enter" not in r.text and "Retracted" not in r.text:
            raise SystemExit("seated")
EOF

